        }
    }

    @Override
    public <P extends IBroomPart> P registerPart(P part) {
        Objects.requireNonNull(part);
        parts.put(part.getId(), part);
        partsByType.put(part.getType(), part);
        return part;
    }

    @Override
    public <P extends IBroomPart> void registerPartItem(@Nullable P part, ItemStack item) {
        if (part != null) {
            Objects.requireNonNull(item.getItem());
            partItems.put(part, item);
        }
    }

    @Override
    public <P extends IBroomPart> void registerBaseModifiers(@Nullable P part, Map<BroomModifier, Float> modifiers) {
        if (part != null) {
            baseModifiers.put(part, modifiers);
        }
    }

    @Override
    public <P extends IBroomPart> void registerBaseModifiers(@Nullable P part, BroomModifier modifier, float modifierValue) {
        Map<BroomModifier, Float> map = Maps.newHashMap();
        map.put(modifier, modifierValue);
        registerBaseModifiers(part, map);
    }

    @Override
    public <P extends IBroomPart> Map<BroomModifier, Float> getBaseModifiersFromPart(P part) {
        if(baseModifiers.containsKey(part)) {
            return baseModifiers.get(part);
        }
        return Collections.emptyMap();
    }

    @Override
    public Map<BroomModifier, Float> getBaseModifiersFromBroom(ItemStack broomStack) {
        Map<BroomModifier, Float> baseModifiers = Maps.newHashMap();
        for (IBroomPart part : getBroomParts(broomStack)) {
            for (Map.Entry<BroomModifier, Float> entry : BroomParts.REGISTRY.getBaseModifiersFromPart(part).entrySet()) {
                BroomModifier modifier = entry.getKey();
                if(baseModifiers.containsKey(modifier)) {
                    baseModifiers.put(modifier, entry.getValue() + baseModifiers.get(modifier));
                } else{
                    baseModifiers.put(modifier, entry.getValue());
                }
            }
        }
        return baseModifiers;
    }

    @Override
    public <P extends IBroomPart> Collection<ItemStack> getItemsFromPart(P part) {
        return Collections.unmodifiableCollection(partItems.get(part));
    }

    @Override
    public <P extends IBroomPart> P getPartFromItem(ItemStack item) {
        for (Map.Entry<IBroomPart, ItemStack> entry : partItems.entries()) {
            if (ItemStack.isSameItemSameTags(item, entry.getValue())) {
                return (P) entry.getKey();
            }
        }
        return null;
    }

    @Override
    public Collection<IBroomPart> getParts() {
        return Collections.unmodifiableCollection(parts.values());
    }

    @Override
    public IBroomPart getPart(ResourceLocation partId) {
        return parts.get(partId);
    }

    @Override
    public Collection<IBroomPart> getParts(IBroomPart.BroomPartType type) {
        return Collections.unmodifiableCollection(partsByType.get(type));
    }

    @Override
    @OnlyIn(Dist.CLIENT)
    public void registerPartModel(IBroomPart part, ResourceLocation modelLocation) {
        partModels.put(part, modelLocation);
    }

    @Override
    @OnlyIn(Dist.CLIENT)
    public ResourceLocation getPartModel(IBroomPart part) {
        return partModels.get(part);
    }

    @Override
    @OnlyIn(Dist.CLIENT)
    public Collection<ResourceLocation> getPartModels() {
        return Collections.unmodifiableCollection(partModels.values());
    }

    @Override
    public Collection<IBroomPart> getBroomParts(ItemStack broomStack) {
        if(!broomStack.isEmpty()) {
            List<IBroomPart> parts = Lists.newArrayList();
            if(broomStack.hasTag()) {
                ListTag tags = broomStack.getTag().getList(NBT_TAG_NAME, Tag.TAG_STRING);
                for (int i = 0; i < tags.size(); i++) {
                    String id = tags.getString(i);
                    IBroomPart part = getPart(new ResourceLocation(id));
                    if (part != null) {
                        parts.add(part);
                    }
                }
            }

            if(parts.isEmpty()) {
                // BroomParts.BRUSH_WHEAT can be null during mod loading
                if (BroomParts.BRUSH_WHEAT != null) {
                    return Lists.newArrayList(BroomParts.BRUSH_WHEAT, BroomParts.CAP_GEM_DARK, BroomParts.ROD_WOOD);
                }
            }

            return parts;
        }
        return Collections.emptyList();
    }

    @Override
    public void setBroomParts(ItemStack broomStack, Collection<IBroomPart> broomParts) {
        ListTag list = new ListTag();
        for (IBroomPart broomPart : broomParts) {
            list.add(StringTag.valueOf(broomPart.getId().toString()));
        }
        if(!broomStack.hasTag()) {
            broomStack.setTag(new CompoundTag());
        }
        broomStack.getTag().put(NBT_TAG_NAME, list);
    }

    @SubscribeEvent
    @OnlyIn(Dist.CLIENT)
    public void onTooltipEvent(ItemTooltipEvent event) {
        if (ItemBroomConfig.broomPartTooltips) {
            IBroomPart part = getPartFromItem(event.getItemStack());
            if (part != null) {
                Map<BroomModifier, Float> modifiers = getBaseModifiersFromPart(part);
                if (!modifiers.isEmpty()) {
                    if (MinecraftHelpers.isShifted()) {
                        event.getToolTip().add(Component.translatable("broom.modifiers." + Reference.MOD_ID + ".types")
                                .withStyle(ChatFormatting.ITALIC));
                        for (Map.Entry<BroomModifier, Float> entry : modifiers.entrySet()) {
                            event.getToolTip().add(entry.getKey().getTooltipLine("  ", entry.getValue(), 0, false));
                        }
                    } else {
                        event.getToolTip().add(Component.translatable("broom.parts." + Reference.MOD_ID + ".shiftinfo")
                                .withStyle(ChatFormatting.ITALIC));
                    }
                }
            }
        }
    }

    @SubscribeEvent(priority = EventPriority.HIGHEST)
    public void beforeItemsRegistered(RegisterEvent event) {
        // The block registry even is called before the items event
        if (event.getRegistryKey().equals(ForgeRegistries.Keys.ITEMS)) {
            parts.clear();
            partItems.clear();
            partsByType.clear();
            baseModifiers.clear();
            if (MinecraftHelpers.isClientSide()) {
                partModels.clear();
            }
        }
    }
}

package org.cyclops.evilcraft.core.degradation;

import net.minecraft.nbt.CompoundTag;
import org.cyclops.evilcraft.EvilCraft;
import org.cyclops.evilcraft.api.degradation.IDegradable;
import org.cyclops.evilcraft.api.degradation.IDegradationEffect;
import org.cyclops.evilcraft.api.degradation.IDegradationRegistry;

/**
 * An executor component to be used by {@link IDegradable}.
 * @author rubensworks
 *
 */
public class DegradationExecutor {

    private static final String ROOT_TAG = "degradationExecutor";
    private static final int DEFAULT_TICK_INTERVAL = 1;

    private int tickInterval = DEFAULT_TICK_INTERVAL;
    private int currentTick = 0;

    private IDegradable degradable;

    /**
     * Make a new instance.
     * @param degradable The {@link IDegradable} this executor applies to.
     */
    public DegradationExecutor(IDegradable degradable) {
        this.degradable = degradable;
    }

    /**
     * Execute a random {@link IDegradationEffect} if the tick is at the correct value that
     * as defined in {@link DegradationExecutor#getTickInterval()}. Each time this method
     * is called, the tick is increased.
     * @param isClientSide True for clients, false for servers.
     * @return If a random effect was executed, can be false if the tick is too small or the
     * randomly chosen effect can not be run.
     */
    public boolean runRandomEffect(boolean isClientSide) {
        currentTick++;
        if(currentTick >= tickInterval) {
            currentTick = 0;
            IDegradationEffect effect = EvilCraft._instance.getRegistryManager().getRegistry(IDegradationRegistry.class).getRandomDegradationEffect();
            if(effect.canRun(degradable)) {
                if(isClientSide) {
                    effect.runClientSide(degradable);
                } else {
                    effect.runServerSide(degradable);
                }
                return true;
            }
        }
        return false;
    }

    /**
     * Reads the data for this executor from NBT.
     * @param compound The tag to read from.
     */
    public void read(CompoundTag compound) {
        this.tickInterval = compound.getCompound(ROOT_TAG).getInt("tickInterval");
        this.currentTick = compound.getCompound(ROOT_TAG).getInt("currentTick");
    }

    /**
     * Writes the data for this executor to NBT.
     * @param compound The tag to write to.
     */
    public void write(CompoundTag compound) {
        CompoundTag content = new CompoundTag();
        content.putInt("tickInterval", tickInterval);
        content.putInt("currentTick", currentTick);
        compound.put(ROOT_TAG, content);
    }

    /**
     * @return the tickInterval
     */
    public int getTickInterval() {
        return tickInterval;
    }

    /**
     * @param tickInterval the tickInterval to set
     */
    public void setTickInterval(int tickInterval) {
        this.tickInterval = tickInterval;
    }

}

package org.cyclops.evilcraft.core.fluid;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.material.Fluid;
import net.minecraft.world.level.material.Fluids;
import net.minecraftforge.fluids.FluidStack;
import org.cyclops.cyclopscore.fluid.SingleUseTank;
import org.cyclops.cyclopscore.helper.MinecraftHelpers;
import org.cyclops.cyclopscore.init.ModBase;
import org.cyclops.cyclopscore.persist.world.WorldStorage;

/**
 * A tank that has shared contents for a given ID.
 * Based on World NBT storage.
 * @author rubensworks
 *
 */
public class WorldSharedTank extends SingleUseTank {

/**
     * The NBT name for the fluid tank.
     */
    public static final String NBT_TANKID = "tankID";

    protected String tankID = "";
    private int previousAmount = 0;

    public WorldSharedTank(int capacity) {
        super(capacity);
    }

    /**
     * Reset the previous fluid storage, used for interpolating fluid amounts client-side.
     */
    public void resetPreviousFluid() {
        previousAmount = getFluidAmount();
    }

    /**
     * Get the previous fluid amount, used for interpolating fluid amounts client-side.
     * @return The previous amount.
     */
    public int getPreviousAmount() {
        return previousAmount;
    }

    @Override
    public void writeTankToNBT(CompoundTag nbt) {
        super.writeTankToNBT(nbt);
        nbt.putString(NBT_TANKID, tankID);
    }

    @Override
    public void readTankFromNBT(CompoundTag nbt) {
        super.readTankFromNBT(nbt);
        tankID = nbt.getString(NBT_TANKID);
    }

    protected void readWorldFluid() {
        this.fluid = WorldSharedTankCache.getInstance().getTankContent(tankID);
    }

    protected void writeWorldFluid() {
        if (!MinecraftHelpers.isClientSideThread()) {
            WorldSharedTankCache.getInstance().setTankContent(tankID, this.fluid);
        }
    }

    @Override
    public void setFluid(FluidStack fluid) {
        super.setFluid(fluid);
        writeWorldFluid();
    }

    @Override
    public FluidStack getFluid() {
        readWorldFluid();
        return super.getFluid();
    }

    @Override
    public int getFluidAmount() {
        readWorldFluid();
        return super.getFluidAmount();
    }

    @Override
    public int getSpace() {
        readWorldFluid();
        return super.getSpace();
    }

    @Override
    public int fill(FluidStack resource, FluidAction action) {
        readWorldFluid();
        int ret = super.fill(resource, action);
        if (ret > 0 && action.execute()) {
            writeWorldFluid();
        }
        return ret;
    }

    @Override
    public FluidStack drain(int maxDrain, FluidAction action) {
        readWorldFluid();
        FluidStack ret = super.drain(maxDrain, action);
        if (!ret.isEmpty() && action.execute()) {
            writeWorldFluid();
        }
        return ret;
    }

    @Override
    public FluidStack drain(FluidStack resource, FluidAction action) {
        readWorldFluid();
        FluidStack ret = super.drain(resource, action);
        if ( !ret.isEmpty() && action.execute()) {
            writeWorldFluid();
        }
        return ret;
    }

    /**
     * Get the tank ID.
     * @return The tank ID.
     */
    public String getTankID() {
        return this.tankID;
    }

    /**
     * Set the tank ID.
     * @param tankID The new tank ID.
     */
    public void setTankID(String tankID) {
        this.tankID = tankID;
    }

    @Override
    public Fluid getAcceptedFluid() {
        Fluid fluid = this.getFluidType();
        return fluid == null ? Fluids.EMPTY : fluid;
    }

    @Override
    protected boolean replaceInnerFluid() {
        return false;
    }

    /**
     * Tank data stored in the world.
     * @author rubensworks
     */
    public static class TankData extends WorldStorage {

        /**
         * NBT key.
         */
        public static final String KEY = "WorldSharedTanks";

        /**
         * Make a new instance.
         * @param mod The mod.
         */
        public TankData(ModBase mod) {
            super(mod);
        }

        @Override
        public void reset() {
            WorldSharedTankCache.getInstance().reset();
        }

        @Override
        protected String getDataId() {
            return KEY;
        }

        @Override
        public void readFromNBT(CompoundTag tag) {
            super.readFromNBT(tag);
            WorldSharedTankCache.getInstance().readFromNBT(tag);
        }

        @Override
        public void writeToNBT(CompoundTag tag) {
            super.writeToNBT(tag);
            WorldSharedTankCache.getInstance().writeToNBT(tag);
        }

    }

}

package org.cyclops.evilcraft.core.fluid;

import com.google.common.collect.Maps;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.server.level.ServerPlayer;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.entity.player.PlayerEvent;
import net.minecraftforge.eventbus.api.EventPriority;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fluids.FluidStack;
import net.minecraftforge.fml.LogicalSide;
import org.cyclops.cyclopscore.helper.MinecraftHelpers;
import org.cyclops.evilcraft.EvilCraft;
import org.cyclops.evilcraft.network.packet.UpdateWorldSharedTankClientCachePacket;

import javax.annotation.Nullable;
import java.util.Iterator;
import java.util.Map;

/**
 * The cache for the shared tank contents.
 * @author rubensworks
 */
public class WorldSharedTankCache {

    /**
     * The amount of ticks inbetween a packet update.
     */
    public static final int INTERPOLATION_TICK_OFFSET = 10;

    private static WorldSharedTankCache _instance = null;

    private Map<String, FluidStack> tankCache = Maps.newHashMap();
    private Map<String, UpdateWorldSharedTankClientCachePacket> packetBuffer = Maps.newHashMap();
    private int tick = 0;

    private WorldSharedTankCache() {

    }

    /**
     * Reset the cache, packet buffer and tick offset.
     */
    public void reset() {
        tankCache = Maps.newHashMap();
        packetBuffer = Maps.newHashMap();
        tick = 0;
    }

    /**
     * Get the unique instance.
     * @return The unique instance.
     */
    public static WorldSharedTankCache getInstance() {
        if(_instance == null) {
            _instance = new WorldSharedTankCache();
        }
        return _instance;
    }

    protected String getMapID(String tankID) {
        return tankID + (MinecraftHelpers.isClientSide() ? "C" : "S");
    }

    protected String removeMapID(String mapID) {
        return mapID.substring(0, mapID.length() - 1);
    }

    /**
     * Get a tank contents.
     * @param tankID The tank.
     * @return The contents.
     */
    public synchronized FluidStack getTankContent(String tankID) {
        FluidStack stack = tankCache.get(getMapID(tankID));
        return (stack == null) ? FluidStack.EMPTY : stack.copy();
    }

    protected static boolean shouldRefreshFluid(@Nullable FluidStack old, FluidStack newF) {
        return (old == null ? 0 : old.getAmount()) != newF.getAmount();
    }

    /**
     * Set the tank contents.
     * @param tankID The id of the tank.
     * @param fluidStack The tank contents.
     */
    public synchronized void setTankContent(String tankID, FluidStack fluidStack) {
        String key = getMapID(tankID);
        boolean shouldRefresh = shouldRefreshFluid(tankCache.get(key), fluidStack);
        if(fluidStack.isEmpty()) {
            tankCache.remove(key);
        } else if(shouldRefresh) {
            tankCache.put(key, fluidStack.copy());
        }
        if(!MinecraftHelpers.isClientSide() && shouldRefresh) {
            bufferPacket(tankID, new UpdateWorldSharedTankClientCachePacket(tankID, fluidStack));
        }
    }

    protected void bufferPacket(String tankID, UpdateWorldSharedTankClientCachePacket packet) {
        packetBuffer.put(tankID, packet);
    }

    /**
     * Get the ticks since last packet flush.
     * @return The tick offset.
     */
    public int getTickOffset() {
        return this.tick;
    }

    /**
     * When a tick event is received.
     * @param event The received event.
     */
    @SubscribeEvent(priority = EventPriority.NORMAL)
    public void onTick(TickEvent event) {
        if(event.phase == TickEvent.Phase.START && (event.type == TickEvent.Type.CLIENT || event.type == TickEvent.Type.SERVER)) {
            tick++;
            if(event.side == LogicalSide.SERVER && getTickOffset() > INTERPOLATION_TICK_OFFSET) {
                Iterator<Map.Entry<String, UpdateWorldSharedTankClientCachePacket>> it = packetBuffer.entrySet().iterator();
                while(it.hasNext()) {
                    EvilCraft._instance.getPacketHandler().sendToAll(it.next().getValue());
                    it.remove();
                }
                tick = 0;
            }
        }
    }

    @SubscribeEvent
    public void onLoggedIn(PlayerEvent.PlayerLoggedInEvent event) {
        if(!MinecraftHelpers.isClientSide()) {
            for(Map.Entry<String, FluidStack> entry: tankCache.entrySet()) {
                EvilCraft._instance.getPacketHandler().sendToPlayer(
                        new UpdateWorldSharedTankClientCachePacket(removeMapID(entry.getKey()), entry.getValue()), (ServerPlayer) event.getEntity());
            }
        }
    }

    /**
     * Read the cache.
     * @param tag The tag to read from.
     */
    public void readFromNBT(CompoundTag tag) {
        if(tag != null) {
            ListTag list = tag.getList("tankCache", 10);
            for (int i = 0; i < list.size(); i++) {
                CompoundTag subTag = list.getCompound(i);
                setTankContent(subTag.getString("key"),
                        FluidStack.loadFluidStackFromNBT(subTag.getCompound("value")));
            }
        }
    }

    /**
     * Write the cache.
     * @param tag The tag to write to.
     */
    public void writeToNBT(CompoundTag tag) {
        ListTag list = new ListTag();
        for(Map.Entry<String, FluidStack> entry : tankCache.entrySet()) {
            CompoundTag subTag = new CompoundTag();
            subTag.putString("key", removeMapID(entry.getKey()));
            CompoundTag fluidTag = new CompoundTag();
            entry.getValue().writeToNBT(fluidTag);
            subTag.put("value", fluidTag);
            list.add(subTag);
        }
        tag.put("tankCache", list);
    }

}

package org.cyclops.evilcraft.core.recipe.type;

import com.mojang.datafixers.util.Either;
import net.minecraft.core.BlockPos;
import net.minecraft.core.RegistryAccess;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.Container;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.Ingredient;
import net.minecraft.world.item.crafting.Recipe;
import net.minecraft.world.item.crafting.RecipeSerializer;
import net.minecraft.world.item.crafting.RecipeType;
import net.minecraft.world.level.Level;
import org.cyclops.cyclopscore.recipe.ItemStackFromIngredient;
import org.cyclops.evilcraft.RegistryEntries;
import org.cyclops.evilcraft.block.BlockEnvironmentalAccumulatorConfig;
import org.cyclops.evilcraft.core.weather.WeatherType;

/**
 * Environmental Accumulator recipe
 * @author rubensworks
 */
public class RecipeEnvironmentalAccumulator implements Recipe<RecipeEnvironmentalAccumulator.Inventory> {

    private final ResourceLocation id;
    private final Ingredient inputIngredient;
    private final WeatherType inputWeather;
    private final Either<ItemStack, ItemStackFromIngredient> outputItem;
    private final WeatherType outputWeather;
    private final int duration;
    private final int cooldownTime;
    private final float processingSpeed;

    public RecipeEnvironmentalAccumulator(ResourceLocation id,
                                          Ingredient inputIngredient, WeatherType inputWeather,
                                          Either<ItemStack, ItemStackFromIngredient> outputItem, WeatherType outputWeather,
                                          int duration, int cooldownTime, float processingSpeed) {
        this.id = id;
        this.inputIngredient = inputIngredient;
        this.inputWeather = inputWeather;
        this.outputItem = outputItem;
        this.outputWeather = outputWeather;
        this.duration = duration;
        this.cooldownTime = cooldownTime;
        this.processingSpeed = processingSpeed;
    }

    public Ingredient getInputIngredient() {
        return inputIngredient;
    }

    public WeatherType getInputWeather() {
        return inputWeather;
    }

    public Either<ItemStack, ItemStackFromIngredient> getOutputItem() {
        return outputItem;
    }

    public ItemStack getOutputItemFirst() {
        return getOutputItem().map(l -> l, ItemStackFromIngredient::getFirstItemStack);
    }

    public WeatherType getOutputWeather() {
        return outputWeather;
    }

    public int getDuration() {
        // Note: we need to do this because defaultProcessItemTickCount is set AFTER the recipes are created
        if (duration < 0)
            return BlockEnvironmentalAccumulatorConfig.defaultProcessItemTickCount;

        return duration;
    }

    public int getCooldownTime() {
        // Note: we need to do this because defaultProcessItemTickCount is set AFTER the recipes are created
        if (cooldownTime < 0)
            return BlockEnvironmentalAccumulatorConfig.defaultTickCooldown;

        return cooldownTime;
    }

    public float getProcessingSpeed() {
        // Note: we need to do this because defaultProcessItemSpeed is set AFTER the recipes are created
        if (processingSpeed < 0)
            return (float) BlockEnvironmentalAccumulatorConfig.defaultProcessItemSpeed;

        return processingSpeed;
    }

    @Override
    public boolean matches(RecipeEnvironmentalAccumulator.Inventory inv, Level worldIn) {
        return inputIngredient.test(inv.getItem(0))
                && inputWeather.isActive(worldIn);
    }

    @Override
    public ItemStack assemble(RecipeEnvironmentalAccumulator.Inventory inv, RegistryAccess registryAccess) {
        ItemStack inputStack = inv.getItem(0);
        ItemStack itemStack = getResultItem(registryAccess).copy();
        if (!inputStack.isEmpty() && inputStack.hasTag()) {
            if(!itemStack.hasTag()) {
                itemStack.setTag(new CompoundTag());
            }
            for (String key : inputStack.getTag().getAllKeys()) {
                if(!itemStack.getTag().contains(key)) {
                    itemStack.getTag().put(key, inputStack.getTag().get(key));
                }
            }
        }
        return itemStack;
    }

    @Override
    public boolean canCraftInDimensions(int width, int height) {
        return width * height <= 1;
    }

    @Override
    public ItemStack getResultItem(RegistryAccess registryAccess) {
        return this.getOutputItemFirst().copy();
    }

    @Override
    public ResourceLocation getId() {
        return this.id;
    }

    @Override
    public RecipeSerializer<?> getSerializer() {
        return RegistryEntries.RECIPESERIALIZER_ENVIRONMENTAL_ACCUMULATOR;
    }

    @Override
    public RecipeType<?> getType() {
        return RegistryEntries.RECIPETYPE_ENVIRONMENTAL_ACCUMULATOR;
    }

    public static interface Inventory extends Container {
        public Level getWorld();
        public BlockPos getPos();
    }

    public static class InventoryDummy extends net.minecraft.world.SimpleContainer implements Inventory {
        public InventoryDummy(ItemStack... stacksIn) {
            super(stacksIn);
        }

        @Override
        public Level getWorld() {
            return null;
        }

        @Override
        public BlockPos getPos() {
            return null;
        }
    }

}

package org.cyclops.evilcraft.core.weather;

import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;

import java.lang.reflect.Field;

/**
 * Abstract class for weather types.
 * @author rubensworks
 *
 */
public abstract class WeatherType {

    /**
     * Any weather type.
     */
    public static final WeatherType ANY = new WeatherTypeAny();
    /**
     * Clear weather.
     */
    public static final WeatherType CLEAR = new WeatherTypeClear();
    /**
     * Rain.
     */
    public static final WeatherType RAIN = new WeatherTypeRain();
    /**
     * Lightning.
     */
    public static final WeatherType LIGHTNING = new WeatherTypeLightning();

    /**
     * Array that contains all possible weather types
     */
    public static final WeatherType[] WEATHER_TYPES = {CLEAR, RAIN, LIGHTNING};

    private final String name;

    protected WeatherType(String name) {
        this.name = name;
    }

    @Override
    public String toString() {
        return this.name;
    }

    /**
     * Check if this weather is active in the given world.
     * @param world The world.
     * @return If it is active.
     */
    public abstract boolean isActive(Level world);

    /**
     * Activate this weather in the given world.
     * @param world The world.
     */
    public abstract void activate(ServerLevel world);
    /**
     * Deactivate this weather in the given world.
     * @param world The world.
     */
    public abstract void deactivate(ServerLevel world);

    /**
     * Activate or deactivate this weather in the given world.
     * @param world The world.
     * @param activate If the weather must be activated.
     */
    public void activate(ServerLevel world, boolean activate) {
        if (activate)
            activate(world);
        else
            deactivate(world);
    }

    /**
     * Returns the current active weather type.
     *
     * @param world The world.
     * @return The current active {@link WeatherType},
     *         or null in case no known active weather
     *         type was found.
     */
    public static WeatherType getActiveWeather(Level world) {
        for (WeatherType type : WEATHER_TYPES) {
            if (type.isActive(world))
                return type;
        }

        return null;
    }

    /**
     * Get a weather type by name.
     * @param type The type name.
     * @return The weather type.
     */
    public static WeatherType valueOf(String type) {
        Field field;
        try {
            field = WeatherType.class.getField(type);
        } catch (NoSuchFieldException e) {
            return null;
        } catch (SecurityException e) {
            return null;
        }
        try {
            return (WeatherType) field.get(null);
        } catch (IllegalArgumentException e) {
            return null;
        } catch (IllegalAccessException e) {
            return null;
        }
    }
}

