    @Override
    public EntityDimensions getDimensions(Pose poseIn) {
        if(isSwarm()) {
            return EntityDimensions.scalable(getSwarmTier() / 3 + 1, getSwarmTier() / 2 + 1);
        }
        LivingEntity innerEntity = getInnerEntity();
        if (innerEntity != null) {
