package de.maxhenkel.corelib.death;

import de.maxhenkel.corelib.item.ItemUtils;
import de.maxhenkel.corelib.player.PlayerUtils;
import net.minecraft.core.BlockPos;
import net.minecraft.core.NonNullList;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;

import java.util.Collection;
import java.util.List;
import java.util.Objects;
import java.util.UUID;
import java.util.stream.Collectors;

public class Death {

    private UUID id;
    private UUID playerUUID;
    private String playerName;

    private NonNullList<ItemStack> mainInventory = NonNullList.withSize(36, ItemStack.EMPTY);
    private NonNullList<ItemStack> armorInventory = NonNullList.withSize(4, ItemStack.EMPTY);
    private NonNullList<ItemStack> offHandInventory = NonNullList.withSize(1, ItemStack.EMPTY);
    private NonNullList<ItemStack> additionalItems = NonNullList.create();

    private NonNullList<ItemStack> equipment = NonNullList.withSize(EquipmentSlot.values().length, ItemStack.EMPTY);

    private long timestamp;
    private int experience;
    private double posX;
    private double posY;
    private double posZ;
    private String dimension;
    private byte model;

    private Death() {

    }

    public UUID getId() {
        return id;
    }

    public UUID getPlayerUUID() {
        return playerUUID;
    }

    public String getPlayerName() {
        return playerName;
    }

    public NonNullList<ItemStack> getMainInventory() {
        return mainInventory;
    }

    public NonNullList<ItemStack> getArmorInventory() {
        return armorInventory;
    }

    public NonNullList<ItemStack> getOffHandInventory() {
        return offHandInventory;
    }

    public NonNullList<ItemStack> getAdditionalItems() {
        return additionalItems;
    }

    public NonNullList<ItemStack> getEquipment() {
        return equipment;
    }

    public long getTimestamp() {
        return timestamp;
    }

    public int getExperience() {
        return experience;
    }

    public double getPosX() {
        return posX;
    }

    public double getPosY() {
        return posY;
    }

    public double getPosZ() {
        return posZ;
    }

    public BlockPos getBlockPos() {
        return BlockPos.containing(posX, posY, posZ);
    }

    public String getDimension() {
        return dimension;
    }

    public byte getModel() {
        return model;
    }

    @Override
    public String toString() {
        return "Death{name=" + playerName + "timestamp=" + timestamp + "}";
    }

    public static Death fromPlayer(Player player) {
        Death death = new Death();
        death.id = UUID.randomUUID();
        death.playerUUID = player.getUUID();
        death.playerName = player.getName().getString();

        for (int i = 0; i < death.mainInventory.size(); i++) {
            death.mainInventory.set(i, player.getInventory().items.get(i));
        }
        for (int i = 0; i < death.armorInventory.size(); i++) {
            death.armorInventory.set(i, player.getInventory().armor.get(i));
        }
        for (int i = 0; i < death.offHandInventory.size(); i++) {
            death.offHandInventory.set(i, player.getInventory().offhand.get(i));
        }
        death.equipment = NonNullList.withSize(EquipmentSlot.values().length, ItemStack.EMPTY);
        for (int i = 0; i < death.equipment.size(); i++) {
            death.equipment.set(i, player.getItemBySlot(EquipmentSlot.values()[i]).copy());
        }

        death.timestamp = System.currentTimeMillis();
        death.experience = player.experienceLevel;
        death.posX = player.getX();
        death.posY = Math.max(player.getY(), player.getRootVehicle().getY());
        death.posZ = player.getZ();
        death.dimension = player.level().dimension().location().toString();
        death.model = PlayerUtils.getModel(player);
        return death;
    }

    /**
     * Matches the actual drops with the items the player had on death.
     *
     * @param items the drops list
     */
    public void processDrops(Collection<ItemEntity> items) {
        List<ItemStack> drops = items.stream()
                .filter(Objects::nonNull)
                .map(ItemEntity::getItem)
                .filter(itemStack -> !itemStack.isEmpty())
                .collect(Collectors.toList());
        processInventory(drops, mainInventory);
        processInventory(drops, armorInventory);
        processInventory(drops, offHandInventory);
        additionalItems.addAll(drops);
    }

    private void processInventory(List<ItemStack> drops, NonNullList<ItemStack> inventory) {
        for (int i = 0; i < inventory.size(); i++) {
            ItemStack itemStack = inventory.get(i);
            if (itemStack.isEmpty()) {
                continue;
            }
            if (drops.contains(itemStack)) {
                drops.remove(itemStack);
            } else {
                inventory.set(i, ItemStack.EMPTY);
            }
        }
    }

    public NonNullList<ItemStack> getAllItems() {
        NonNullList<ItemStack> items = NonNullList.create();
        items.addAll(filterList(mainInventory));
        items.addAll(filterList(armorInventory));
        items.addAll(filterList(offHandInventory));
        items.addAll(filterList(additionalItems));
        return items;
    }

    private List<ItemStack> filterList(List<ItemStack> stacks) {
        return stacks.stream().filter(itemStack -> !itemStack.isEmpty()).collect(Collectors.toList());
    }

    public static Death fromNBT(CompoundTag compound) {
        Death death = new Death();
        if (compound.contains("IdMost") && compound.contains("IdLeast")) {
            death.id = new UUID(compound.getLong("IdMost"), compound.getLong("IdLeast"));
        } else if (compound.contains("Id")) {
            death.id = compound.getUUID("Id");
        } else {
            death.id = UUID.randomUUID();
        }
        if (compound.contains("PlayerUuidMost") && compound.contains("PlayerUuidLeast")) {
            death.playerUUID = new UUID(compound.getLong("PlayerUuidMost"), compound.getLong("PlayerUuidLeast"));
        } else if (compound.contains("PlayerUuid")) {
            death.playerUUID = compound.getUUID("PlayerUuid");
        } else {
            death.playerUUID = UUID.randomUUID();
        }
        death.playerName = compound.getString("PlayerName");

        ItemUtils.readInventory(compound, "MainInventory", death.mainInventory);
        ItemUtils.readInventory(compound, "ArmorInventory", death.armorInventory);
        ItemUtils.readInventory(compound, "OffHandInventory", death.offHandInventory);

        death.additionalItems = ItemUtils.readItemList(compound, "Items");

        ItemUtils.readItemList(compound, "Equipment", death.equipment);

        death.timestamp = compound.getLong("Timestamp");
        death.experience = compound.getInt("Experience");
        death.posX = compound.getDouble("PosX");
        death.posY = compound.getDouble("PosY");
        death.posZ = compound.getDouble("PosZ");
        death.dimension = compound.getString("Dimension");
        death.model = compound.getByte("Model");

        return death;
    }

    public CompoundTag toNBT() {
        return toNBT(true);
    }

    public CompoundTag toNBT(boolean withItems) {
        CompoundTag compound = new CompoundTag();
        compound.putUUID("Id", id);
        compound.putUUID("PlayerUuid", playerUUID);
        compound.putString("PlayerName", playerName);

        if (withItems) {
            ItemUtils.saveInventory(compound, "MainInventory", mainInventory);
            ItemUtils.saveInventory(compound, "ArmorInventory", armorInventory);
            ItemUtils.saveInventory(compound, "OffHandInventory", offHandInventory);
            ItemUtils.saveItemList(compound, "Items", additionalItems);
        }

        ItemUtils.saveItemList(compound, "Equipment", equipment);

        compound.putLong("Timestamp", timestamp);
        compound.putInt("Experience", experience);
        compound.putDouble("PosX", posX);
        compound.putDouble("PosY", posY);
        compound.putDouble("PosZ", posZ);
        compound.putString("Dimension", dimension);
        compound.putByte("Model", model);

        return compound;
    }

    public static class Builder {
        private Death death;

        public Builder(UUID playerUUID, UUID id) {
            death = new Death();
            death.dimension = "";
            death.playerName = "";
            death.playerUUID = playerUUID;
            death.id = id;
        }

        public Death build() {
            return death;
        }

        public Builder id(UUID uuid) {
            death.id = uuid;
            return this;
        }

        public Builder playerUUID(UUID uuid) {
            death.playerUUID = uuid;
            return this;
        }

        public Builder playerName(String name) {
            death.playerName = name;
            return this;
        }

        public Builder mainInventory(NonNullList<ItemStack> list) {
            death.mainInventory = list;
            return this;
        }

        public Builder armorInventory(NonNullList<ItemStack> list) {
            death.armorInventory = list;
            return this;
        }

        public Builder offHandInventory(NonNullList<ItemStack> list) {
            death.offHandInventory = list;
            return this;
        }

        public Builder additionalItems(NonNullList<ItemStack> list) {
            death.additionalItems = list;
            return this;
        }

        public Builder equipment(NonNullList<ItemStack> list) {
            death.equipment = list;
            return this;
        }

        public Builder timestamp(long timestamp) {
            death.timestamp = timestamp;
            return this;
        }

        public Builder experience(int experience) {
            death.experience = experience;
            return this;
        }

        public Builder posX(double posX) {
            death.posX = posX;
            return this;
        }

        public Builder posY(double posY) {
            death.posY = posY;
            return this;
        }

        public Builder posZ(double posZ) {
            death.posZ = posZ;
            return this;
        }

        public Builder dimension(String dimension) {
            death.dimension = dimension;
            return this;
        }

        public Builder model(byte model) {
            death.model = model;
            return this;
        }
    }

}

package de.maxhenkel.corelib.death;

import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.event.entity.living.LivingDeathEvent;
import net.minecraftforge.event.entity.living.LivingDropsEvent;
import net.minecraftforge.eventbus.api.EventPriority;
import net.minecraftforge.eventbus.api.SubscribeEvent;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.Map;

public final class DeathEvents {

    private Map<ServerPlayer, Death> deathMap = new HashMap<>();

    @SubscribeEvent(priority = EventPriority.LOWEST)
    void playerDeath(LivingDeathEvent event) {
        Entity entity = event.getEntity();
        if (!(entity instanceof ServerPlayer)) {
            return;
        }
        ServerPlayer player = (ServerPlayer) event.getEntity();
        deathMap.put(player, Death.fromPlayer(player));
    }

    @SubscribeEvent(priority = EventPriority.LOWEST)
    void playerDeath(LivingDropsEvent event) {
        Entity entity = event.getEntity();
        if (!(entity instanceof ServerPlayer)) {
            return;
        }
        try {
            ServerPlayer player = (ServerPlayer) event.getEntity();
            Death death = deathMap.remove(player);

            if (death == null) {
                death = Death.fromPlayer(player);
            }
            Collection<ItemEntity> drops = event.getDrops();
            death.processDrops(new ArrayList<>(drops));

            PlayerDeathEvent playerDeathEvent = new PlayerDeathEvent(death, player, event.getSource());
            MinecraftForge.EVENT_BUS.post(playerDeathEvent);

            if (playerDeathEvent.isStoreDeath()) {
                DeathManager.addDeath(player, death);
            }
            if (playerDeathEvent.isRemoveDrops()) {
                drops.clear();
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Registers the events in order to emit the {@link PlayerDeathEvent}
     * NOTE: This removes drops from getting spawned
     */
    public static void register() {
        MinecraftForge.EVENT_BUS.register(new DeathEvents());
    }

}

package de.maxhenkel.corelib.death;

import de.maxhenkel.corelib.CommonUtils;
import de.maxhenkel.corelib.Logger;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.NbtIo;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.storage.LevelResource;

import javax.annotation.Nullable;
import java.io.File;
import java.util.*;
import java.util.stream.Collectors;

public class DeathManager {

    /**
     * The name of the folder that stores all player deaths
     */
    public static LevelResource DEATHS = new LevelResource("deaths");

    /**
     * Adds a death to the deaths folder as the provided player
     *
     * @param player the player under which the death should get stored
     * @param death  the death to store
     */
    public static void addDeath(ServerPlayer player, Death death) {
        try {
            File deathFile = getDeathFile(player, death.getId());
            deathFile.getParentFile().mkdirs();
            NbtIo.write(death.toNBT(), deathFile);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Gets the death with the provided ID of a specific player
     *
     * @param player the player
     * @param id     the death ID
     * @return the death
     */
    @Nullable
    public static Death getDeath(ServerPlayer player, UUID id) {
        return getDeath(player.serverLevel(), player.getUUID(), id);
    }

    /**
     * Gets the death with the provided ID of a specific player
     *
     * @param world      the world
     * @param playerUUID the players UUID
     * @param id         the death ID
     * @return the death
     */
    @Nullable
    public static Death getDeath(ServerLevel world, UUID playerUUID, UUID id) {
        try {
            CompoundTag data = NbtIo.read(getDeathFile(world, playerUUID, id));
            if (data == null) {
                return null;
            }
            return Death.fromNBT(data);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    /**
     * Reads the death from the provided file
     *
     * @param file the death file
     * @return the death
     */
    @Nullable
    public static Death getDeath(File file) {
        try {
            CompoundTag data = NbtIo.read(file);
            if (data == null) {
                return null;
            }
            return Death.fromNBT(data);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    /**
     * Gets a death from its ID
     * Note that this searches for every players deaths
     *
     * @param world the world
     * @param id    the death id
     * @return the death
     */
    @Nullable
    public static Death getDeath(ServerLevel world, UUID id) {
        File deathFolder = getDeathFolder(world);
        File[] players = deathFolder.listFiles((dir, name) -> name.matches("^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"));

        if (players == null) {
            return null;
        }

        for (File f : players) {
            if (!f.isDirectory()) {
                continue;
            }
            File[] files = f.listFiles((dir, name) -> name.equals(id.toString() + ".dat"));
            if (files != null && files.length > 0) {
                return getDeath(world, UUID.fromString(f.getName()), id);
            }
        }
        return null;
    }

    /**
     * Gets all deaths of a player
     *
     * @param player the player
     * @return all deaths of the player
     */
    public static List<Death> getDeaths(ServerPlayer player) {
        return getDeaths(player);
    }

    /**
     * Gets all deaths of a player
     *
     * @param world      the world - used to get the death folder location
     * @param playerUUID the UUID of the player
     * @return a list containing all deaths of the player
     */
    public static List<Death> getDeaths(ServerLevel world, UUID playerUUID) {
        File playerDeathFolder = getPlayerDeathFolder(world, playerUUID);

        if (!playerDeathFolder.exists()) {
            return Collections.emptyList();
        }

        File[] deaths = playerDeathFolder.listFiles((dir, name) -> name.matches("^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\\.dat$"));

        if (deaths == null) {
            return Collections.emptyList();
        }

        return Arrays.stream(deaths)
                .map(f -> {
                    try {
                        return Death.fromNBT(NbtIo.read(f));
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                    return null;
                })
                .filter(Objects::nonNull)
                .sorted(Comparator.comparingLong(Death::getTimestamp).reversed())
                .collect(Collectors.toList());
    }

    /**
     * Deletes the death file from the filesystem
     *
     * @param world the world
     * @param death the death to delete
     * @return if the death was deleted from the filesystem
     */
    public static boolean removeDeath(ServerLevel world, Death death) {
        File file = getDeathFile(world, death.getPlayerUUID(), death.getId());
        if (file.exists()) {
            return file.delete();
        }
        return true;
    }

    /**
     * Deletes all deaths that are older than the provided time
     *
     * @param world the world
     * @param age   the age in milliseconds
     */
    public static void removeDeathsOlderThan(ServerLevel world, long age) {
        long now = System.currentTimeMillis();
        File deathFolder = getDeathFolder(world);
        File[] players = deathFolder.listFiles((dir, name) -> name.matches("^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"));

        if (players == null) {
            return;
        }

        for (File f : players) {
            if (!f.isDirectory()) {
                continue;
            }
            File[] deaths = f.listFiles(file -> (now - file.lastModified()) > age);
            if (deaths == null) {
                continue;
            }
            for (File d : deaths) {
                Death death = getDeath(d);
                if (death == null) {
                    continue;
                }
                if ((now - death.getTimestamp()) > age) {
                    if (d.delete()) {
                        Logger.INSTANCE.info("Removed death file of '{}' ({}), since it is older than {} milliseconds", death.getPlayerName(), death.getId().toString(), age);
                    }
                }
            }
        }
    }

    /**
     * Gets the death file of a player with the provided death ID
     *
     * @param player the player
     * @param id     the death ID
     * @return the death file
     */
    public static File getDeathFile(ServerPlayer player, UUID id) {
        return new File(getPlayerDeathFolder(player), id.toString() + ".dat");
    }

    /**
     * Gets the death file of a player with the provided death ID
     *
     * @param world      the world
     * @param playerUUID the players UUID
     * @param id         the death ID
     * @return the death file
     */
    public static File getDeathFile(ServerLevel world, UUID playerUUID, UUID id) {
        return new File(getPlayerDeathFolder(world, playerUUID), id.toString() + ".dat");
    }

    /**
     * Get the deaths folder of a player
     *
     * @param player the player
     * @return the deaths folder
     */
    public static File getPlayerDeathFolder(ServerPlayer player) {
        return getPlayerDeathFolder(player.serverLevel(), player.getUUID());
    }

    /**
     * Get the deaths folder of a player
     *
     * @param world the world - used to get the death folder location
     * @param uuid  the UUID of the player
     * @return the deaths folder
     */
    public static File getPlayerDeathFolder(ServerLevel world, UUID uuid) {
        return new File(getDeathFolder(world), uuid.toString());
    }

    /**
     * Gets the folder containing the players deaths
     *
     * @param world the world - used to get the death folder location
     * @return the player deaths folder
     */
    public static File getDeathFolder(ServerLevel world) {
        return CommonUtils.getWorldFolder(world, DEATHS);
    }
}

package de.maxhenkel.corelib.item;

import net.minecraft.core.NonNullList;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.world.Container;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.items.ItemHandlerHelper;

import java.util.Comparator;

public class ItemUtils {

    /**
     * Does not compare compound entries, just if they are the same hashcode
     */
    public static final Comparator<ItemStack> ITEM_COMPARATOR = (item1, item2) -> {
        int cmp = item2.getItem().hashCode() - item1.getItem().hashCode();
        if (cmp != 0) {
            return cmp;
        }
        cmp = item2.getDamageValue() - item1.getDamageValue();
        if (cmp != 0) {
            return cmp;
        }
        CompoundTag c1 = item1.getTag();
        CompoundTag c2 = item2.getTag();

        if (c1 == null && c2 == null) {
            return 0;
        } else if (c1 == null) {
            return 1;
        } else if (c2 == null) {
            return -1;
        }

        return c1.hashCode() - c2.hashCode();
    };

    /**
     * Changes the item stack amount. If a player is provided and the player is in Creative Mode, the stack wont be changed
     *
     * @param amount the amount to change
     * @param stack  the Item Stack
     * @param player the player (Can be null)
     * @return the resulting stack
     */
    public static ItemStack itemStackAmount(int amount, ItemStack stack, Player player) {
        if (stack == null || stack.isEmpty()) {
            return ItemStack.EMPTY;
        }

        if (player != null && player.getAbilities().instabuild) {
            return stack;
        }

        stack.setCount(stack.getCount() + amount);
        if (stack.getCount() <= 0) {
            stack.setCount(0);
            return ItemStack.EMPTY;
        }

        if (stack.getCount() > stack.getMaxStackSize()) {
            stack.setCount(stack.getMaxStackSize());
        }

        return stack;
    }

    public static ItemStack decrItemStack(ItemStack stack, Player player) {
        return itemStackAmount(-1, stack, player);
    }

    public static ItemStack incrItemStack(ItemStack stack, Player player) {
        return itemStackAmount(1, stack, player);
    }

    /**
     * Compares two stacks except its NBT data
     *
     * @param stack1 the first stack
     * @param stack2 the second stack
     * @return if the two stacks are equal
     */
    public static boolean areItemsEqual(ItemStack stack1, ItemStack stack2) {
        if (stack1 == null || stack2 == null) {
            return false;
        }
        if (stack1.getItem() == stack2.getItem()) {
            return stack1.getDamageValue() == stack2.getDamageValue();
        }
        return false;
    }

    /**
     * Stores the provided inventory to the provided compound under the given name
     *
     * @param compound the compound to save the inventory to
     * @param name     the name of the tag list in the compound
     * @param inv      the inventory
     */
    public static void saveInventory(CompoundTag compound, String name, Container inv) {
        ListTag tagList = new ListTag();

        for (int i = 0; i < inv.getContainerSize(); i++) {
            if (!inv.getItem(i).isEmpty()) {
                CompoundTag slot = new CompoundTag();
                slot.putInt("Slot", i);
                inv.getItem(i).save(slot);
                tagList.add(slot);
            }
        }

        compound.put(name, tagList);
    }

    /**
     * Stores the provided item list to the provided compound under the given name
     *
     * @param compound the compound to save the inventory to
     * @param name     the name of the tag list in the compound
     * @param inv      the item list
     */
    public static void saveInventory(CompoundTag compound, String name, NonNullList<ItemStack> inv) {
        ListTag tagList = new ListTag();
        for (int i = 0; i < inv.size(); i++) {
            if (!inv.get(i).isEmpty()) {
                CompoundTag slot = new CompoundTag();
                slot.putInt("Slot", i);
                inv.get(i).save(slot);
                tagList.add(slot);
            }
        }

        compound.put(name, tagList);
    }

    /**
     * Stores the provided item list to the provided compound under the given name
     * Stores empty items
     *
     * @param compound the compound to save the inventory to
     * @param name     the name of the tag list in the compound
     * @param list     the item list
     */
    public static void saveItemList(CompoundTag compound, String name, NonNullList<ItemStack> list) {
        saveItemList(compound, name, list, true);
    }

    /**
     * Stores the provided item list to the provided compound under the given name
     * Stores empty items
     *
     * @param compound     the compound to save the inventory to
     * @param name         the name of the tag list in the compound
     * @param list         the item list
     * @param includeEmpty if empty item stacks should be included
     */
    public static void saveItemList(CompoundTag compound, String name, NonNullList<ItemStack> list, boolean includeEmpty) {
        ListTag itemList = new ListTag();
        for (ItemStack stack : list) {
            if (!includeEmpty && stack.isEmpty()) {
                continue;
            }
            itemList.add(stack.save(new CompoundTag()));
        }
        compound.put(name, itemList);
    }

    /**
     * Loads the provided compound to the provided inventory
     * Does not clear inventory - empty stacks will not overwrite existing items
     *
     * @param compound the compound to read the inventory from
     * @param name     the name of the tag list in the compound
     * @param inv      the inventory
     */
    public static void readInventory(CompoundTag compound, String name, Container inv) {
        if (!compound.contains(name)) {
            return;
        }

        ListTag tagList = compound.getList(name, 10);

        for (int i = 0; i < tagList.size(); i++) {
            CompoundTag slot = tagList.getCompound(i);
            int j = slot.getInt("Slot");

            if (j >= 0 && j < inv.getContainerSize()) {
                inv.setItem(j, ItemStack.of(slot));
            }
        }
    }

    /**
     * Loads the provided compound to the provided item list
     * Does not clear the list - empty stacks will not overwrite existing items
     *
     * @param compound the compound to read the inventory from
     * @param name     the name of the tag list in the compound
     * @param inv      the item list
     */
    public static void readInventory(CompoundTag compound, String name, NonNullList<ItemStack> inv) {
        if (!compound.contains(name)) {
            return;
        }

        ListTag tagList = compound.getList(name, 10);

        for (int i = 0; i < tagList.size(); i++) {
            CompoundTag slot = tagList.getCompound(i);
            int j = slot.getInt("Slot");

            if (j >= 0 && j < inv.size()) {
                inv.set(j, ItemStack.of(slot));
            }
        }
    }

    /**
     * Loads the provided compound to the provided item list
     *
     * @param compound     the compound to read the item list from
     * @param name         the name of the tag list in the compound
     * @param includeEmpty if empty stacks should be included
     * @return the item list
     */
    public static NonNullList<ItemStack> readItemList(CompoundTag compound, String name, boolean includeEmpty) {
        NonNullList<ItemStack> items = NonNullList.create();
        if (!compound.contains(name)) {
            return items;
        }

        ListTag itemList = compound.getList(name, 10);
        for (int i = 0; i < itemList.size(); i++) {
            ItemStack item = ItemStack.of(itemList.getCompound(i));
            if (!includeEmpty) {
                if (!item.isEmpty()) {
                    items.add(item);
                }
            } else {
                items.add(item);
            }
        }
        return items;
    }

    /**
     * Loads the provided compound to the provided item list
     * Inclues empty items
     *
     * @param compound the compound to read the item list from
     * @param name     the name of the tag list in the compound
     * @return the item list
     */
    public static NonNullList<ItemStack> readItemList(CompoundTag compound, String name) {
        return readItemList(compound, name, true);
    }

    /**
     * Reads the compound into the item list
     * Only fills the list to its maximum capacity
     *
     * @param compound the compound to read the item list from
     * @param name     the name of the tag list in the compound
     * @param list     the item list
     */
    public static void readItemList(CompoundTag compound, String name, NonNullList<ItemStack> list) {
        if (!compound.contains(name)) {
            return;
        }

        ListTag itemList = compound.getList(name, 10);
        for (int i = 0; i < itemList.size(); i++) {
            if (i >= list.size()) {
                break;
            }
            list.set(i, ItemStack.of(itemList.getCompound(i)));
        }
    }

    /**
     * Removes the provided slot from the provided inventory
     *
     * @param inventory the inventory
     * @param index     the slot index
     */
    public static void removeStackFromSlot(Container inventory, int index) {
        inventory.setItem(index, ItemStack.EMPTY);
    }

    /**
     * Returns if the provided stacks are stackable on each other
     *
     * @param stack1 the first stack
     * @param stack2 the second stack
     * @return if the provided stacks are stackable on each other
     */
    public static boolean isStackable(ItemStack stack1, ItemStack stack2) {
        return ItemHandlerHelper.canItemStacksStack(stack1, stack2);
    }

    /**
     * Writes the provided item stack to the provided NBT compound.
     * Ignores the maximum stack size of the stack.
     * Can stack up to the integer limit.
     *
     * @param compound the compound to store the stack in
     * @param stack    the stack to store
     * @return the provided compound
     */
    public static CompoundTag writeOverstackedItem(CompoundTag compound, ItemStack stack) {
        stack.save(compound);
        compound.remove("Count");
        compound.putInt("Count", stack.getCount());
        return compound;
    }

    /**
     * Reads the provided item stack from the provided NBT compound.
     * Ignores the maximum stack size of the stack.
     * Can stack up to the integer limit.
     *
     * @param compound the compound to store the stack in
     * @return the deserialized stack
     */
    public static ItemStack readOverstackedItem(CompoundTag compound) {
        CompoundTag data = compound.copy();
        int count = data.getInt("Count");
        data.remove("Count");
        data.putByte("Count", (byte) 1);
        ItemStack stack = ItemStack.of(data);
        stack.setCount(count);
        return stack;
    }
}

package de.maxhenkel.corpse.entities;

import de.maxhenkel.corelib.death.Death;
import de.maxhenkel.corelib.item.ItemUtils;
import de.maxhenkel.corelib.net.NetUtils;
import de.maxhenkel.corpse.Main;
import de.maxhenkel.corpse.gui.Guis;
import de.maxhenkel.corpse.net.MessageSpawnDeathParticles;
import net.minecraft.core.NonNullList;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientGamePacketListener;
import net.minecraft.network.protocol.game.ClientboundAddEntityPacket;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.network.syncher.EntityDataSerializers;
import net.minecraft.network.syncher.SynchedEntityData;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.tags.DamageTypeTags;
import net.minecraft.tags.FluidTags;
import net.minecraft.world.Containers;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.api.distmarker.OnlyIn;

import java.util.Optional;
import java.util.UUID;

public class CorpseEntity extends CorpseBoundingBoxBase {

    private static final EntityDataAccessor<Optional<UUID>> ID = SynchedEntityData.defineId(CorpseEntity.class, EntityDataSerializers.OPTIONAL_UUID);
    private static final EntityDataAccessor<String> NAME = SynchedEntityData.defineId(CorpseEntity.class, EntityDataSerializers.STRING);
    private static final EntityDataAccessor<Boolean> SKELETON = SynchedEntityData.defineId(CorpseEntity.class, EntityDataSerializers.BOOLEAN);
    private static final EntityDataAccessor<Byte> MODEL = SynchedEntityData.defineId(CorpseEntity.class, EntityDataSerializers.BYTE);
    private static final EntityDataAccessor<NonNullList<ItemStack>> EQUIPMENT = SynchedEntityData.defineId(CorpseEntity.class, Main.ITEM_LIST_SERIALIZER.get());

    private int age;
    private int emptyAge;

    protected Death death;

    public CorpseEntity(EntityType type, Level world) {
        super(type, world);
        blocksBuilding = true;
        emptyAge = -1;
        death = new Death.Builder(new UUID(0L, 0L), new UUID(0L, 0L)).build();
    }

    public CorpseEntity(Level world) {
        this(Main.CORPSE_ENTITY_TYPE.get(), world);
    }

    public static CorpseEntity createFromDeath(Player player, Death death) {
        CorpseEntity corpse = new CorpseEntity(player.level());
        corpse.death = death;
        corpse.setCorpseUUID(death.getPlayerUUID());
        corpse.setCorpseName(death.getPlayerName());
        corpse.setEquipment(death.getEquipment());
        corpse.setPos(death.getPosX(), Math.max(death.getPosY(), player.level().getMinBuildHeight()), death.getPosZ());
        corpse.setYRot(player.getYRot());
        corpse.setCorpseModel(death.getModel());
        return corpse;
    }

    @Override
    protected float getEyeHeight(Pose poseIn, EntityDimensions sizeIn) {
        return sizeIn.height * 0.35F;
    }

    @Override
    public void tick() {
        super.tick();
        if (!isNoGravity()) {
            double yMotion = 0D;
            Vec3 motion = getDeltaMovement();
            if (isEyeInFluid(FluidTags.WATER) || isEyeInFluid(FluidTags.LAVA)) {
                if (motion.y < 0D) {
                    yMotion = motion.y + (motion.y < 0.03D ? 0.01D : 0D);
                } else {
                    yMotion = motion.y + (motion.y < 0.03D ? 5E-4D : 0D);
                }
            } else if (Main.SERVER_CONFIG.fallIntoVoid.get() || getY() > level().getMinBuildHeight()) {
                yMotion = Math.max(-2D, motion.y - 0.0625D);
            }
            setDeltaMovement(getDeltaMovement().x * 0.75D, yMotion, getDeltaMovement().z * 0.75D);

            if (!Main.SERVER_CONFIG.fallIntoVoid.get() && getY() < level().getMinBuildHeight()) {
                teleportTo(getX(), level().getMinBuildHeight(), getZ());
            }

            move(MoverType.SELF, getDeltaMovement());
        }

        if (level().isClientSide) {
            return;
        }

        age++;
        setIsSkeleton(age >= Main.SERVER_CONFIG.corpseSkeletonTime.get());

        if (Main.SERVER_CONFIG.corpseForceDespawnTime.get() > 0 && age > Main.SERVER_CONFIG.corpseForceDespawnTime.get()) {
            discard();
            return;
        }
        boolean empty = isEmpty();
        if (empty && emptyAge < 0) {
            emptyAge = age;
        } else if (empty && age - emptyAge >= Main.SERVER_CONFIG.corpseDespawnTime.get()) {
            discard();
        }
    }

    public boolean isMainInventoryEmpty() {
        return death.getMainInventory().stream().allMatch(ItemStack::isEmpty)
                && death.getArmorInventory().stream().allMatch(ItemStack::isEmpty)
                && death.getOffHandInventory().stream().allMatch(ItemStack::isEmpty);
    }

    public boolean isAdditionalInventoryEmpty() {
        return death.getAdditionalItems().stream().allMatch(ItemStack::isEmpty);
    }

    public boolean isEmpty() {
        return isMainInventoryEmpty() && isAdditionalInventoryEmpty();
    }

    @Override
    public boolean hurt(DamageSource source, float amount) {
        if (Main.SERVER_CONFIG.lavaDamage.get() && source.is(DamageTypeTags.IS_FIRE) && amount >= 2F) {
            discard();
        }
        return super.hurt(source, amount);
    }

    @Override
    public InteractionResult interact(Player player, InteractionHand hand) {
        if (!level().isClientSide && player instanceof ServerPlayer) {
            ServerPlayer playerMP = (ServerPlayer) player;
            if (Main.SERVER_CONFIG.onlyOwnerAccess.get()) {
                boolean isOp = playerMP.hasPermissions(playerMP.server.getOperatorUserPermissionLevel());
                if (isOp || !getCorpseUUID().isPresent() || playerMP.getUUID().equals(getCorpseUUID().get())) {
                    Guis.openCorpseGUI((ServerPlayer) player, this);
                } else if (Main.SERVER_CONFIG.skeletonAccess.get() && isSkeleton()) {
                    Guis.openCorpseGUI((ServerPlayer) player, this);
                }
            } else {
                Guis.openCorpseGUI((ServerPlayer) player, this);
            }
        }
        return InteractionResult.SUCCESS;
    }

    @Override
    public Component getDisplayName() {
        String name = getCorpseName();
        if (name == null || name.trim().isEmpty()) {
            return super.getDisplayName();
        } else {
            return Component.translatable("entity.corpse.corpse_of", getCorpseName());
        }
    }

    @Override
    public boolean displayFireAnimation() {
        return false;
    }


    @OnlyIn(Dist.CLIENT)
    @Override
    public AABB getBoundingBoxForCulling() {
        return getBoundingBox();
    }

    @Override
    public boolean isPickable() {
        return isAlive();
    }

    public Optional<UUID> getCorpseUUID() {
        return entityData.get(ID);
    }

    public void setCorpseUUID(UUID uuid) {
        if (uuid == null) {
            entityData.set(ID, Optional.empty());
        } else {
            entityData.set(ID, Optional.of(uuid));
        }
    }

    public Death getDeath() {
        return death;
    }

    @OnlyIn(Dist.CLIENT)
    public void setDeath(Death death) {
        this.death = death;
    }

    public String getCorpseName() {
        return entityData.get(NAME);
    }

    public void setCorpseName(String name) {
        entityData.set(NAME, name);
    }

    public boolean isSkeleton() {
        return entityData.get(SKELETON);
    }

    public void setIsSkeleton(boolean skeleton) {
        entityData.set(SKELETON, skeleton);
    }

    public byte getCorpseModel() {
        return entityData.get(MODEL);
    }

    public void setCorpseModel(byte model) {
        entityData.set(MODEL, model);
    }

    public void setEquipment(NonNullList<ItemStack> equipment) {
        entityData.set(EQUIPMENT, equipment);
    }

    public NonNullList<ItemStack> getEquipment() {
        return entityData.get(EQUIPMENT);
    }

    @Override
    protected void defineSynchedData() {
        entityData.define(ID, Optional.empty());
        entityData.define(NAME, "");
        entityData.define(SKELETON, false);
        entityData.define(MODEL, (byte) 0);
        entityData.define(EQUIPMENT, NonNullList.withSize(EquipmentSlot.values().length, ItemStack.EMPTY));
    }

    @Override
    public void remove(RemovalReason reason) {
        for (ItemStack item : death.getAllItems()) {
            Containers.dropItemStack(level(), getX(), getY(), getZ(), item);
        }
        super.remove(reason);
        if (level() instanceof ServerLevel serverWorld) {
            serverWorld.getPlayers(player -> player.distanceToSqr(getX(), getY(), getZ()) <= 64D * 64D).forEach(playerEntity -> NetUtils.sendTo(Main.SIMPLE_CHANNEL, playerEntity, new MessageSpawnDeathParticles(getUUID())));
        }
    }

    public void spawnDeathParticles() {
        double x = getX();
        double y = getY();
        double z = getZ();
        Vec3 lookVec = getLookAngle().normalize();
        for (int i = 0; i <= 10; i++) {
            double d = ((((double) i) / 10D) - 0.5D) * 2D;
            level().addParticle(ParticleTypes.LARGE_SMOKE, x + lookVec.x * d + (level().random.nextDouble() - 0.5D), y + 0.25D, z + lookVec.z * d + (level().random.nextDouble() - 0.5D), 0D, 0D, 0D);
        }
    }

    @Override
    protected void readAdditionalSaveData(CompoundTag compound) {
        if (compound.contains("Death")) {
            death = Death.fromNBT(compound.getCompound("Death"));
        } else { // Compatibility
            UUID playerUUID = new UUID(compound.getLong("IDMost"), compound.getLong("IDLeast"));
            UUID deathID = new UUID(compound.getLong("DeathIDMost"), compound.getLong("DeathIDLeast"));

            Death.Builder builder = new Death.Builder(playerUUID, deathID);

            int size = compound.getInt("InventorySize");
            NonNullList<ItemStack> additionalItems = NonNullList.withSize(size, ItemStack.EMPTY);
            ItemUtils.readInventory(compound, "Inventory", additionalItems);
            builder.additionalItems(additionalItems);
            NonNullList<ItemStack> equipment = NonNullList.withSize(EquipmentSlot.values().length, ItemStack.EMPTY);
            ItemUtils.readItemList(compound, "Equipment", equipment);
            builder.equipment(equipment);
            builder.playerName(compound.getString("Name"));
            death = builder.build();
        }
        setEquipment(death.getEquipment());
        setCorpseUUID(death.getPlayerUUID());
        setCorpseName(death.getPlayerName());
        setCorpseModel(death.getModel());
        age = compound.getInt("Age");
        if (compound.contains("EmptyAge")) {
            emptyAge = compound.getInt("EmptyAge");
        }
    }

    @Override
    protected void addAdditionalSaveData(CompoundTag compound) {
        compound.put("Death", death.toNBT());
        compound.putInt("Age", age);
        if (emptyAge >= 0) {
            compound.putInt("EmptyAge", emptyAge);
        }
    }

    @Override
    public Packet<ClientGamePacketListener> getAddEntityPacket() {
        return new ClientboundAddEntityPacket(this);
    }
}

package de.maxhenkel.corpse.events;

import de.maxhenkel.corelib.death.DeathManager;
import de.maxhenkel.corelib.death.PlayerDeathEvent;
import de.maxhenkel.corpse.Main;
import de.maxhenkel.corpse.entities.CorpseEntity;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraftforge.eventbus.api.SubscribeEvent;

public class DeathEvents {

    public DeathEvents() {
        de.maxhenkel.corelib.death.DeathEvents.register();
    }

    @SubscribeEvent
    public void playerDeath(PlayerDeathEvent event) {
        if (Main.SERVER_CONFIG.maxDeathAge.get() != 0) {
            event.storeDeath();
        }
        event.removeDrops();

        ServerPlayer player = event.getPlayer();

        player.serverLevel().addFreshEntity(CorpseEntity.createFromDeath(player, event.getDeath()));

        deleteOldDeaths(player.serverLevel());
    }

    public static void deleteOldDeaths(ServerLevel serverWorld) {
        int ageInDays = Main.SERVER_CONFIG.maxDeathAge.get();
        if (ageInDays < 0) {
            return;
        }
        long ageInMillis = ((long) ageInDays) * 24L * 60L * 60L * 1000L;
        //TODO Use an executor
        new Thread(() -> DeathManager.removeDeathsOlderThan(serverWorld, ageInMillis)).start();
    }

}

package de.maxhenkel.corpse.gui;

import de.maxhenkel.corelib.inventory.ItemListInventory;
import de.maxhenkel.corelib.inventory.LockedSlot;
import de.maxhenkel.corpse.Main;
import de.maxhenkel.corpse.entities.CorpseEntity;
import net.minecraft.world.SimpleContainer;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.items.wrapper.PlayerMainInvWrapper;

public class CorpseAdditionalContainer extends CorpseContainerBase implements ITransferrable {

    private PlayerMainInvWrapper playerWrapper;

    public CorpseAdditionalContainer(int id, Inventory playerInventory, CorpseEntity corpse, boolean editable, boolean history) {
        super(Main.CONTAINER_TYPE_CORPSE_ADDITIONAL_ITEMS.get(), id, playerInventory, corpse, editable, history);
        this.inventory = new ItemListInventory(corpse.getDeath().getAdditionalItems());
        this.playerWrapper = new PlayerMainInvWrapper(playerInventory);

        setSlots(0);
    }

    public void setSlots(int start) {
        slots.clear();
        for (int j = 0; j < 6; j++) {
            for (int k = 0; k < 9; k++) {
                int index = start + k + j * 9;
                if (index < inventory.getContainerSize()) {
                    addSlot(new LockedSlot(inventory, index, 8 + k * 18, 19 + j * 18, true, !editable));
                } else {
                    addSlot(new LockedSlot(new SimpleContainer(1), 0, 8 + k * 18, 19 + j * 18, true, true));
                }
            }
        }

        addPlayerInventorySlots();
        broadcastChanges();
    }

    @Override
    public void transferItems() {
        if (!isEditable()) {
            return;
        }
        for (int i = 0; i < inventory.getContainerSize(); i++) {
            ItemStack stack = inventory.getItem(i);
            for (int j = 0; j < playerWrapper.getSlots(); j++) {
                stack = playerWrapper.insertItem(j, stack, false);
                inventory.setItem(i, stack);
                if (stack.isEmpty()) {
                    break;
                }
            }
        }
    }

    @Override
    public int getInvOffset() {
        return 82;
    }

    @Override
    public int getInventorySize() {
        return 54;
    }
}

