package de.maxhenkel.corpse.gui;

import com.mojang.datafixers.util.Pair;
import de.maxhenkel.corelib.inventory.ItemListInventory;
import de.maxhenkel.corelib.inventory.LockedSlot;
import de.maxhenkel.corpse.Main;
import de.maxhenkel.corpse.entities.CorpseEntity;
import net.minecraft.core.NonNullList;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.Container;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.inventory.InventoryMenu;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.api.distmarker.OnlyIn;

import java.util.List;

public class CorpseInventoryContainer extends CorpseContainerBase implements ITransferrable {

    private static final ResourceLocation[] ARMOR_SLOT_TEXTURES = new ResourceLocation[]{InventoryMenu.EMPTY_ARMOR_SLOT_BOOTS, InventoryMenu.EMPTY_ARMOR_SLOT_LEGGINGS, InventoryMenu.EMPTY_ARMOR_SLOT_CHESTPLATE, InventoryMenu.EMPTY_ARMOR_SLOT_HELMET};

    private ItemListInventory mainInventory;
    private ItemListInventory armorInventory;
    private ItemListInventory offHandInventory;

    public CorpseInventoryContainer(int id, Inventory playerInventory, CorpseEntity corpse, boolean editable, boolean history) {
        super(Main.CONTAINER_TYPE_CORPSE_INVENTORY.get(), id, playerInventory, corpse, editable, history);

        mainInventory = new ItemListInventory(corpse.getDeath().getMainInventory());
        armorInventory = new ItemListInventory(corpse.getDeath().getArmorInventory());
        offHandInventory = new ItemListInventory(corpse.getDeath().getOffHandInventory());

        for (int i = 0; i < 4; i++) {
            int slotIndex = 3 - i;
            addSlot(new LockedSlot(armorInventory, slotIndex, 8 + i * 18, 18, true, !editable) {
                @OnlyIn(Dist.CLIENT)
                @Override
                public Pair<ResourceLocation, ResourceLocation> getNoItemIcon() {
                    return Pair.of(InventoryMenu.BLOCK_ATLAS, ARMOR_SLOT_TEXTURES[slotIndex]);
                }
            });
        }

        addSlot(new LockedSlot(offHandInventory, 0, 98, 18, true, !editable) {
            @OnlyIn(Dist.CLIENT)
            @Override
            public Pair<ResourceLocation, ResourceLocation> getNoItemIcon() {
                return Pair.of(InventoryMenu.BLOCK_ATLAS, InventoryMenu.EMPTY_ARMOR_SLOT_SHIELD);
            }
        });

        int k;
        for (k = 0; k < 3; ++k) {
            for (int j = 0; j < 9; ++j) {
                addSlot(new LockedSlot(mainInventory, j + k * 9 + 9, 8 + j * 18, 40 + k * 18, true, !editable));
            }
        }

        for (k = 0; k < 9; ++k) {
            addSlot(new LockedSlot(mainInventory, k, 8 + k * 18, 98, true, !editable));
        }

        addPlayerInventorySlots();
    }

    @Override
    public void transferItems() {
        if (!isEditable()) {
            return;
        }

        if (!(playerInventory.player instanceof ServerPlayer)) {
            return;
        }

        ServerPlayer player = (ServerPlayer) playerInventory.player;

        NonNullList<ItemStack> additionalItems = NonNullList.create();
        fill(additionalItems, mainInventory, playerInventory.items);
        fill(additionalItems, armorInventory, playerInventory.armor);
        fill(additionalItems, offHandInventory, playerInventory.offhand);

        additionalItems.addAll(corpse.getDeath().getAdditionalItems());
        NonNullList<ItemStack> restItems = NonNullList.create();
        for (ItemStack stack : additionalItems) {
            if (!player.getInventory().add(stack)) {
                restItems.add(stack);
            }
        }

        corpse.getDeath().getAdditionalItems().clear();
        corpse.getDeath().getAdditionalItems().addAll(restItems);
        if (!corpse.getDeath().getAdditionalItems().isEmpty()) {
            Guis.openAdditionalItems(player, this);
        }
    }

    private void fill(List<ItemStack> additionalItems, Container inventory, NonNullList<ItemStack> playerInv) {
        for (int i = 0; i < inventory.getContainerSize(); i++) {
            ItemStack stack = inventory.getItem(i);
            if (stack.isEmpty()) {
                continue;
            }
            ItemStack playerStack = playerInv.get(i);
            if (!playerStack.isEmpty()) {
                additionalItems.add(playerStack);
            }
            inventory.setItem(i, ItemStack.EMPTY);
            playerInv.set(i, stack);
        }
    }

    @Override
    public void broadcastChanges() {
        super.broadcastChanges();
        if (corpse.isMainInventoryEmpty() && !corpse.isAdditionalInventoryEmpty() && playerInventory.player instanceof ServerPlayer) {
            Guis.openAdditionalItems((ServerPlayer) playerInventory.player, this);
        }
    }

    @Override
    public int getInvOffset() {
        return 79;
    }

    @Override
    public int getInventorySize() {
        return 41;
    }
}

package de.maxhenkel.corpse.gui;

import de.maxhenkel.corelib.death.Death;
import de.maxhenkel.corelib.death.DeathManager;
import de.maxhenkel.corpse.entities.CorpseEntity;
import net.minecraft.server.level.ServerPlayer;
import net.minecraftforge.network.NetworkHooks;

import java.util.UUID;

public class Guis {

    public static void openAdditionalItems(ServerPlayer player, CorpseInventoryContainer container) {
        openAdditionalItems(player, container.getCorpse(), container.isEditable(), container.isHistory());
    }

    public static void openAdditionalItems(ServerPlayer player, CorpseEntity corpse, boolean editable, boolean history) {
        NetworkHooks.openScreen(player, new CorpseAdditionalItemsContainerProvider(corpse, editable, history), packetBuffer -> {
            packetBuffer.writeBoolean(history);
            packetBuffer.writeBoolean(corpse.isAdditionalInventoryEmpty());
            if (history) {
                packetBuffer.writeNbt(corpse.getDeath().toNBT(false));
            } else {
                packetBuffer.writeUUID(corpse.getUUID());
            }
        });
    }

    public static void openCorpseGUI(ServerPlayer player, CorpseEntity corpse, boolean editable, boolean history) {
        if (corpse.isMainInventoryEmpty() && !corpse.isEmpty()) {
            openAdditionalItems(player, corpse, editable, history);
        } else {
            NetworkHooks.openScreen(player, new CorpseContainerProvider(corpse, editable, history), packetBuffer -> {
                packetBuffer.writeBoolean(history);
                packetBuffer.writeBoolean(corpse.isAdditionalInventoryEmpty());
                if (history) {
                    packetBuffer.writeNbt(corpse.getDeath().toNBT(false));
                } else {
                    packetBuffer.writeUUID(corpse.getUUID());
                }
            });
        }
    }

    /**
     * Called when actually interacting with the corpse
     *
     * @param player the player
     * @param corpse the corpse
     */
    public static void openCorpseGUI(ServerPlayer player, CorpseEntity corpse) {
        openCorpseGUI(player, corpse, true, false);
    }

    /**
     * Called when opening the corpse inventory from commands or the history
     *
     * @param playerToShow the player that gets the screen
     * @param player       the player the death is from
     * @param uuid         the death id
     */
    public static void openCorpseGUI(ServerPlayer playerToShow, UUID player, UUID uuid) {
        Death death = DeathManager.getDeath(playerToShow.serverLevel(), player, uuid);
        if (death == null) {
            return;
        }
        CorpseEntity corpse = CorpseEntity.createFromDeath(playerToShow, death);
        openCorpseGUI(playerToShow, corpse, playerToShow.getAbilities().instabuild, true);
    }

}

package de.maxhenkel.corpse.net;

import de.maxhenkel.corelib.death.Death;
import de.maxhenkel.corelib.death.DeathManager;
import de.maxhenkel.corelib.net.Message;
import de.maxhenkel.corpse.Main;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.server.level.ServerPlayer;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.network.NetworkDirection;
import net.minecraftforge.network.NetworkEvent;

import java.util.List;
import java.util.UUID;

public class MessageRequestDeathHistory implements Message {

    public MessageRequestDeathHistory() {

    }

    @Override
    public Dist getExecutingSide() {
        return Dist.DEDICATED_SERVER;
    }

    @Override
    public void executeServerSide(NetworkEvent.Context context) {
        sendDeathHistory(context.getSender());
    }

    @Override
    public MessageRequestDeathHistory fromBytes(FriendlyByteBuf buf) {
        return this;
    }

    @Override
    public void toBytes(FriendlyByteBuf buf) {

    }

    public static boolean sendDeathHistory(ServerPlayer player) {
        return sendDeathHistory(player, player.getUUID());
    }

    public static boolean sendDeathHistory(ServerPlayer playerToSend, UUID playerUUID) {
        List<Death> deaths = DeathManager.getDeaths(playerToSend.serverLevel(), playerUUID);
        if (deaths == null) {
            return false;
        }
        Main.SIMPLE_CHANNEL.sendTo(new MessageOpenHistory(deaths), playerToSend.connection.connection, NetworkDirection.PLAY_TO_CLIENT);
        return true;
    }
}

package de.maxhenkel.corpse.net;

import de.maxhenkel.corelib.net.Message;
import de.maxhenkel.corpse.gui.Guis;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.network.NetworkEvent;

import java.util.UUID;

public class MessageShowCorpseInventory implements Message {

    private UUID playerUUID;
    private UUID deathID;

    public MessageShowCorpseInventory() {

    }

    public MessageShowCorpseInventory(UUID playerUUID, UUID deathID) {
        this.playerUUID = playerUUID;
        this.deathID = deathID;
    }

    @Override
    public Dist getExecutingSide() {
        return Dist.DEDICATED_SERVER;
    }

    @Override
    public void executeServerSide(NetworkEvent.Context context) {
        Guis.openCorpseGUI(context.getSender(), playerUUID, deathID);
    }

    @Override
    public MessageShowCorpseInventory fromBytes(FriendlyByteBuf buf) {
        playerUUID = new UUID(buf.readLong(), buf.readLong());
        deathID = new UUID(buf.readLong(), buf.readLong());
        return this;
    }

    @Override
    public void toBytes(FriendlyByteBuf buf) {
        buf.writeLong(playerUUID.getMostSignificantBits());
        buf.writeLong(playerUUID.getLeastSignificantBits());
        buf.writeLong(deathID.getMostSignificantBits());
        buf.writeLong(deathID.getLeastSignificantBits());
    }
}

package de.maxhenkel.corpse.net;

import de.maxhenkel.corelib.net.Message;
import de.maxhenkel.corpse.gui.ITransferrable;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.network.NetworkEvent;

public class MessageTransferItems implements Message {

    public MessageTransferItems() {

    }

    @Override
    public Dist getExecutingSide() {
        return Dist.DEDICATED_SERVER;
    }

    @Override
    public void executeServerSide(NetworkEvent.Context context) {
        AbstractContainerMenu openContainer = context.getSender().containerMenu;
        if ((openContainer instanceof ITransferrable) && !context.getSender().isDeadOrDying()) {
            ITransferrable transferrable = (ITransferrable) openContainer;
            transferrable.transferItems();
        }
    }

    @Override
    public MessageTransferItems fromBytes(FriendlyByteBuf buf) {
        return this;
    }

    @Override
    public void toBytes(FriendlyByteBuf buf) {

    }

}
